export type HTMLBeginnerDraftEntry = {
  id: string;
  sequence: number;
  existingLessonId?: string;
  titleAr: string;
  titleEn: string;
  objectiveAr: string;
  objectiveEn: string;
  commonMistakesAr: string[];
  commonMistakesEn: string[];
  newContent?: {
    steps: Array<{
      titleAr: string;
      titleEn: string;
      bodyAr: string;
      bodyEn: string;
      examples: Array<{ code: string; explanationAr: string; explanationEn: string }>;
    }>;
    exerciseAr: string;
    exerciseEn: string;
    quiz: {
      promptAr: string;
      promptEn: string;
      choices: Array<{ id: string; ar: string; en: string }>;
      correctChoiceId: string;
      correctFeedbackAr: string;
      correctFeedbackEn: string;
      incorrectFeedbackAr: string;
      incorrectFeedbackEn: string;
      reviewAr: string;
      reviewEn: string;
    };
  };
};

type AddedLesson = Omit<HTMLBeginnerDraftEntry, 'id' | 'sequence' | 'newContent'> & {
  id: `html-b-${string}`;
  steps: NonNullable<HTMLBeginnerDraftEntry['newContent']>['steps'];
  exerciseAr: string;
  exerciseEn: string;
  quiz: NonNullable<HTMLBeginnerDraftEntry['newContent']>['quiz'];
};

function added(sequence: number, lesson: AddedLesson): HTMLBeginnerDraftEntry {
  const { steps, exerciseAr, exerciseEn, quiz, ...entry } = lesson;
  return { ...entry, sequence, newContent: { steps, exerciseAr, exerciseEn, quiz } };
}

function preserved(
  sequence: number,
  id: string,
  titleAr: string,
  titleEn: string,
  objectiveAr: string,
  objectiveEn: string,
  commonMistakesAr: string[],
  commonMistakesEn: string[],
): HTMLBeginnerDraftEntry {
  return { id, existingLessonId: id, sequence, titleAr, titleEn, objectiveAr, objectiveEn, commonMistakesAr, commonMistakesEn };
}

